<template>
<div class="my-popups">
    <loader :is-visible="Loading"></loader>
    <div class="modal my-popups right fade d-block" :class="{ show: isShown }">
        <div role="document" class="modal-dialog" style="max-width: 1200px !important;">
            <div class="modal-content">
                <div class="modal-header theme-primary partition-full d-flex">
                    <h4 class="modal-title">Copy Contract(s) to Biller</h4>
                    <button type="button" class="close" @click="Close">
                        <em class="fa fa-times" aria-hidden="true"></em>
                    </button>
                </div>
                <div class="modal-body">
                    <div class="tab-content">
                        <div class="tab-pane active show">
                            <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0">
                                <div class="col-lg-12 float-left p-0">
                                    <dynamic-form lang="en" ref="CopyContractForm" :schema="FormSchema"></dynamic-form>
                                </div>
                                <div class="col-lg-12 float-left p-0">
                                    <div class="col-12 p-0 d-flex flex-wrap mb-2">
                                        <div class="col-12 p-0">
                                            <div class="row m-0">
                                                <div class="heading-border mb-2">
                                                    <h5 class="h5">
                                                        <span>Selected Contracts ({{ filteredContracts.length }})</span>
                                                    </h5>
                                                </div>
                                                <div class="pt-2 d-inline-block w-100">
                                                    <div class="col-12 p-0 mt-0">
                                                        <div class="col-6 col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pr-1 pl-0">
                                                            <input maxlength="50" class="form-control" type="text" v-model="Searchtext" placeholder="Search by Contract Name" autocomplete="off">
                                                        </div>
                                                        <div class="col-6 col-sm-6 col-md-6 col-lg-6 col-xl-6 float-left pl-0">
                                                            <div class="search-btm-btn background-0 form-check-inline">
                                                                <button title="Search" @click="SearchButton(Searchtext)" class="btn btn-success mr-1 px-4">
                                                                    <em class="fa fa-search"></em> Search
                                                                </button>
                                                                <button title="Clear" class="btn btn-danger px-4" @click="Clear">
                                                                    <em class="fa fa-refresh"></em> Clear
                                                                </button>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                                <div class="col-md-12 p-0">
                                                    <div class="listing mt-2">
                                                        <div class="table-responsive table-fix-header float-left">
                                                            <table class="table table-bordered mt-0" style="width:100%">
                                                                <thead class="thead-bg">
                                                                    <tr>
                                                                        <th style="width:30%">Contract Name</th>
                                                                        <th class="text-center" style="width:10%">
                                                                            {{ $t('Flag') }}<br>
                                                                            <div class="form-group mb-0">
                                                                                <label class="switch">
                                                                                    <input type="checkbox" v-model="allFlag">
                                                                                    <span class="slider round">
                                                                                        <span class="slider-yes">{{ $t('Yes') }}</span>
                                                                                        <span class="slider-no text-right pr-1">{{ $t('No') }}</span>
                                                                                    </span>
                                                                                </label>
                                                                            </div>
                                                                        </th>
                                                                        <th class="text-center" style="width:10%">
                                                                            {{ $t('Invoice') }}<br>
                                                                            <div class="form-group mb-0">
                                                                                <label class="switch">
                                                                                    <input type="checkbox" v-model="allInvoice">
                                                                                    <span class="slider round">
                                                                                        <span class="slider-yes">{{ $t('Yes') }}</span>
                                                                                        <span class="slider-no text-right pr-1">{{ $t('No') }}</span>
                                                                                    </span>
                                                                                </label>
                                                                            </div>
                                                                        </th>
                                                                        <th class="text-center" style="width:10%">
                                                                            {{ $t('Unprocess') }}<br>
                                                                            <div class="form-group mb-0">
                                                                                <label class="switch">
                                                                                    <input type="checkbox" v-model="allUnprocess">
                                                                                    <span class="slider round">
                                                                                        <span class="slider-yes">{{ $t('Yes') }}</span>
                                                                                        <span class="slider-no text-right pr-1">{{ $t('No') }}</span>
                                                                                    </span>
                                                                                </label>
                                                                            </div>
                                                                        </th>
                                                                        <th class="text-center" style="width:12%">
                                                                            {{ $t('BilledUnbilled') }}<br>
                                                                            <div class="form-group mb-0">
                                                                                <label class="switch">
                                                                                    <input type="checkbox" v-model="allBilledUnbilled">
                                                                                    <span class="slider round">
                                                                                        <span class="slider-yes">{{ $t('Yes') }}</span>
                                                                                        <span class="slider-no text-right pr-1">{{ $t('No') }}</span>
                                                                                    </span>
                                                                                </label>
                                                                            </div>
                                                                        </th>
                                                                        <th class="text-center" style="width:12%">
                                                                            {{ $t('RateSchedule') }}<br>
                                                                            <div class="form-group mb-0">
                                                                                <label class="switch">
                                                                                    <input type="checkbox" v-model="allRateSchedule">
                                                                                    <span class="slider round">
                                                                                        <span class="slider-yes">{{ $t('Yes') }}</span>
                                                                                        <span class="slider-no text-right pr-1">{{ $t('No') }}</span>
                                                                                    </span>
                                                                                </label>
                                                                            </div>
                                                                        </th>
                                                                        <th class="text-center" style="width:12%">
                                                                            {{ $t('BillingRule') }}<br>
                                                                            <div class="form-group mb-0">
                                                                                <label class="switch">
                                                                                    <input type="checkbox" v-model="allBillingRule">
                                                                                    <span class="slider round">
                                                                                        <span class="slider-yes">{{ $t('Yes') }}</span>
                                                                                        <span class="slider-no text-right pr-1">{{ $t('No') }}</span>
                                                                                    </span>
                                                                                </label>
                                                                            </div>
                                                                        </th>
                                                                        <th class="text-center" style="width:12%">
                                                                            {{ $t('Report') }}<br>
                                                                            <div class="form-group mb-0">
                                                                                <label class="switch">
                                                                                    <input type="checkbox" v-model="allReport">
                                                                                    <span class="slider round">
                                                                                        <span class="slider-yes">{{ $t('Yes') }}</span>
                                                                                        <span class="slider-no text-right pr-1">{{ $t('No') }}</span>
                                                                                    </span>
                                                                                </label>
                                                                            </div>
                                                                        </th>
                                                                    </tr>
                                                                </thead>
                                                                <tbody>
                                                                    <tr v-for="contract in filteredContracts" :key="rowKey(contract)">
                                                                        <td><span :title="stripHtml(contract.contractName)" v-html="contract.contractName"></span></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="contract.isFlag"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="contract.isInvoice"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="contract.isUnprocess"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="contract.isBilledUnbilled"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="contract.isRateSchedule"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="contract.isBillingRule"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                        <td><label class="switch"><input type="checkbox" v-model="contract.isReport"><span class="slider round"><span class="slider-yes">{{ $t('Yes') }}</span><span class="slider-no">{{ $t('No') }}</span></span></label></td>
                                                                    </tr>
                                                                    <tr v-if="filteredContracts.length === 0">
                                                                        <td colspan="8" class="text-danger text-center">{{ $t('NorecordfoundText') }}</td>
                                                                    </tr>
                                                                </tbody>
                                                            </table>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                            <div class="clearfix"></div>
                                            <div class="row flex-row-reverse mt-2">
                                                <div class="col-lg-6 text-right">
                                                    <div class="search-btm-btn">
                                                        <button @click="CopyContracts" class="btn btn-success" style="float:right;margin-left: 10px">
                                                            <i class="fa fa-copy pr-2"></i><span>Copy Contracts</span>
                                                        </button>
                                                        <button @click="Close" style="float:right;" class="btn btn-danger">
                                                            <em class="fa fa-close pr-2"></em>{{ $t('Cancel') }}
                                                        </button>
                                                    </div>
                                                </div>
                                                <div class="col-lg-6">
                                                    <div class="py-2">
                                                        <span class="mandatory">{{ $t('MandatoryString') }}</span>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>
</template>

<script>
import DataService from '../../services/DataService';

export default {
    props: {
        selectedContracts: {
            type: Array,
            required: true,
            default: () => []
        },
        currentBillerId: {
            type: [Number, String],
            required: false,
            default: 0
        }
    },
    data() {
        return {
            Loading: false,
            isShown: false,
            Searchtext: '',
            contractsMaster: [],
            filteredContracts: [],
            FormSchema: [{
                layoutType: "single",
                Data: [
                    {
                        astype: "SearchableSelectField",
                        label: "Assign these to Biller",
                        name: "Biller",
                        value: "",
                        placeholder: "Enter Biller name to assign...",
                        visibility: true,
                        isSearch: true,
                        config: {
                            options: [],
                            actionButtons: { clear: true },
                            isMultiple: false,
                            itemFields: ['text'],
                            minSearchLength: 0
                        },
                        disabled: false,
                        validationRules: { "required": true }
                    }
                ]
            }]
        };
    },
    computed: {
        allFlag: {
            get() { return this.contractsMaster.length > 0 && this.contractsMaster.every(c => c.isFlag === true); },
            set(v) { this.contractsMaster.forEach(c => { c.isFlag = v; }); }
        },
        allInvoice: {
            get() { return this.contractsMaster.length > 0 && this.contractsMaster.every(c => c.isInvoice === true); },
            set(v) { this.contractsMaster.forEach(c => { c.isInvoice = v; }); }
        },
        allUnprocess: {
            get() { return this.contractsMaster.length > 0 && this.contractsMaster.every(c => c.isUnprocess === true); },
            set(v) { this.contractsMaster.forEach(c => { c.isUnprocess = v; }); }
        },
        allBilledUnbilled: {
            get() { return this.contractsMaster.length > 0 && this.contractsMaster.every(c => c.isBilledUnbilled === true); },
            set(v) { this.contractsMaster.forEach(c => { c.isBilledUnbilled = v; }); }
        },
        allRateSchedule: {
            get() { return this.contractsMaster.length > 0 && this.contractsMaster.every(c => c.isRateSchedule === true); },
            set(v) { this.contractsMaster.forEach(c => { c.isRateSchedule = v; }); }
        },
        allBillingRule: {
            get() { return this.contractsMaster.length > 0 && this.contractsMaster.every(c => c.isBillingRule === true); },
            set(v) { this.contractsMaster.forEach(c => { c.isBillingRule = v; }); }
        },
        allReport: {
            get() { return this.contractsMaster.length > 0 && this.contractsMaster.every(c => c.isReport === true); },
            set(v) { this.contractsMaster.forEach(c => { c.isReport = v; }); }
        }
    },
    created() {
        this.contractsMaster = (this.selectedContracts || []).map(c => ({
            clientId: Number(c.clientId || 0),
            contractName: c.contractName || '',
            isFlag: !!c.isFlag,
            isInvoice: !!c.isInvoice,
            isUnprocess: !!c.isUnprocess,
            isBilledUnbilled: !!c.isBilledUnbilled,
            isRateSchedule: !!c.isRateSchedule,
            isBillingRule: !!c.isBillingRule,
            isReport: !!c.isReport
        }));
        this.filteredContracts = this.contractsMaster.slice();
    },
    mounted() {
        this.$nextTick(() => {
            this.isShown = true;
            this.GetBillerList();
        });
    },
    methods: {
        stripHtml(s) {
            if (!s) return '';
            return String(s).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        },
        rowKey(c) {
            return `${c.clientId}`;
        },
        async GetBillerList() {
            const vm = this;
            vm.Loading = true;
            try {
                const url = 'reqFrom=all&moduleName=Billing&IncludeBiller=YES';
                const response = await DataService.GetBillerList(url);
                const parsed = JSON.parse(response.data.result || '[]');
                const sourceBillerId = Number(vm.currentBillerId || 0);
                const options = parsed.map(item => ({
                    text: item.USERNAME,
                    value: item.USERID,
                    displayValue: item.USERNAME
                })).filter(item => Number(item.value) !== sourceBillerId);
                const field = vm.FormSchema[0].Data.find(f => f.name === 'Biller');
                if (field) field.config.options = options;
                vm.$refs.CopyContractForm?.UpdateKeyValue();
            } catch (e) {
                console.error('GetBillerList error:', e);
            } finally {
                vm.Loading = false;
            }
        },
        SearchButton(txt) {
            const query = (txt || '').trim().toLowerCase();
            if (!query) {
                this.filteredContracts = this.contractsMaster.slice();
                return;
            }
            this.filteredContracts = this.contractsMaster.filter(c => this.stripHtml(c.contractName).toLowerCase().includes(query));
        },
        Clear() {
            this.Searchtext = '';
            this.filteredContracts = this.contractsMaster.slice();
        },
        async CopyContracts() {
            const targetBillerId = Number(this.FormSchema?.[0]?.Data?.[0]?.value || 0);
            if (!targetBillerId) {
                this.ShowAlert("Please select a biller", "warning", true);
                return;
            }
            if (!this.contractsMaster.length) {
                this.ShowAlert("No contracts selected to copy", "warning", true);
                return;
            }
            const payload = {
                targetBillerId: targetBillerId,
                selectedContracts: this.contractsMaster.map(c => ({
                    clientId: Number(c.clientId),
                    isFlag: !!c.isFlag,
                    isInvoice: !!c.isInvoice,
                    isUnprocess: !!c.isUnprocess,
                    isBilledUnbilled: !!c.isBilledUnbilled,
                    isRateSchedule: !!c.isRateSchedule,
                    isBillingRule: !!c.isBillingRule,
                    isReport: !!c.isReport
                }))
            };
            this.Loading = true;
            try {
                const response = await DataService.CopyContractsToBiller(payload);
                const isSuccess = response?.data?.status === 'Success' || response?.data?.Status === 'Success' || response?.data?.Code === "1" || response?.data?.code === "1";
                if (!isSuccess) {
                    throw new Error(response?.data?.msg || response?.data?.Msg || "Failed to copy contracts");
                }
                this.ShowAlert("Contracts copied successfully", "success", true);
                this.$emit('copied');
            } catch (e) {
                this.ShowAlert(e.message || "Failed to copy contracts", "danger", true);
            } finally {
                this.Loading = false;
            }
        },
        Close() {
            this.$emit('close');
        }
    }
};
</script>
